package dev.pocketengine.browser;

import java.util.UUID;
import dev.pocketengine.features.plugins.PluginRules;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

/** Pure source contract; explicit native-frame fixtures do not assert a physical provider was exercised. */
public final class BrowserFrameSourceContractTest {
    static JSONObject j(Object...p)throws Exception {JSONObject j=new JSONObject();for(int i=0;i<p.length;i+=2)j.put((String)p[i],p[i+1]);return j;}
    static final String MAIN="main_document_rendered_light_and_open_shadow_dom",CHILD="selected_frame_rendered_light_and_open_shadow_dom",URL="https://embed.example/report?owner=private";
    static final String DOC=UUID.randomUUID().toString(),TOP=UUID.randomUUID().toString(),FRAME=UUID.randomUUID().toString();
    static JSONObject row(String id,String doc,String origin,boolean main,boolean read)throws Exception {return j("frameId",id,"documentId",doc,"sourceOrigin",origin,"mainFrame",main,"read",read);}
    static JSONObject child()throws Exception {return j("schemaVersion",2,"featureSupported",true,"execution","isolated_world","fallbackReason",JSONObject.NULL,"knownOriginMatchedFrames",new JSONArray().put(row("main",TOP,"https://top.example",true,false)).put(row(FRAME,DOC,"https://embed.example",false,true)),"frameTreeComplete",false,"childFrameContentsRead",true,"automaticReload",false,"selectedFrameId",FRAME,"selectedDocumentId",DOC,"selectedSourceOrigin","https://embed.example","topDocumentId",TOP,"parentPageIdentityDigest","a".repeat(64),"selectedDocumentKind","http_document","sourceUrlRole","selected_document_url");}
    static void validate(JSONObject value)throws Exception {BrowserTaskSourcePort.validateFrameCoverage(value,FRAME,DOC,CHILD,URL);}
    @Test public void actualSelectedFrameSourceRetainsItsOwnOriginDocumentAndContainerVersion()throws Exception {JSONObject value=child();validate(value);assertNotEquals(value.getString("topDocumentId"),value.getString("selectedDocumentId"));assertFalse(value.getBoolean("frameTreeComplete"));assertFalse(value.getBoolean("automaticReload"));}
    @Test public void otherDocumentOrFrameCannotBeAcceptedAsThisSavedSource()throws Exception {assertThrows(SecurityException.class,()->validate(child().put("selectedDocumentId",UUID.randomUUID().toString())));assertThrows(SecurityException.class,()->validate(child().put("selectedFrameId",UUID.randomUUID().toString())));assertThrows(SecurityException.class,()->validate(child().put("selectedSourceOrigin","https://another.example")));}
    @Test public void fallbackCannotPretendThatItReadAChildOrBypassedMissingProviderFeature()throws Exception {assertThrows(SecurityException.class,()->validate(child().put("execution","page_world_fallback").put("fallbackReason","provider_feature_unsupported")));assertThrows(SecurityException.class,()->validate(child().put("featureSupported",false)));}
    @Test public void readFlagsMustMatchExactlyOneActuallySelectedNativeFrame()throws Exception {JSONObject wrong=child();wrong.getJSONArray("knownOriginMatchedFrames").getJSONObject(0).put("read",true);assertThrows(SecurityException.class,()->validate(wrong));JSONObject absent=child();absent.getJSONArray("knownOriginMatchedFrames").getJSONObject(1).put("read",false);assertThrows(SecurityException.class,()->validate(absent));}
    @Test public void coverageCannotUpgradeIncompleteTreeOrAddAuthorityFields()throws Exception {assertThrows(SecurityException.class,()->validate(child().put("frameTreeComplete",true)));assertThrows(SecurityException.class,()->validate(child().put("permissionGranted",true)));assertThrows(SecurityException.class,()->validate(child().put("automaticReload",true)));assertThrows(SecurityException.class,()->validate(child().put("parentPageIdentityDigest","unknown")));}
    @Test public void inlineFrameUsesExplicitContainerUrlRoleNotAnInventedHttpResource()throws Exception {String host="https://top.example/host?private=owner";JSONObject value=child().put("selectedDocumentKind","inline_srcdoc").put("sourceUrlRole","inline_document_host_page").put("parentPageIdentityDigest",dev.pocketengine.store.TaskStore.capabilityFingerprint(j("url",host)));BrowserTaskSourcePort.validateFrameCoverage(value,FRAME,DOC,CHILD,host);assertThrows(SecurityException.class,()->BrowserTaskSourcePort.validateFrameCoverage(value,FRAME,DOC,CHILD,URL));}
    @Test public void legacySavedMainCoverageStaysReadableButCannotBecomeChildEvidence()throws Exception {JSONObject old=BrowserSemanticReadTest.frame();BrowserTaskSourcePort.validateFrameCoverage(old,"main",DOC,MAIN,"https://top.example/page");assertThrows(SecurityException.class,()->BrowserTaskSourcePort.validateFrameCoverage(old,FRAME,DOC,CHILD,URL));}
    @Test public void actualPluginRulesAcceptReadFrameSchemaAndRejectAuthorityOrActionRefs()throws Exception {String frame=UUID.randomUUID().toString();JSONObject args=j("mode","text","frameRef",frame);PluginRules.validateArguments(args,BrowserSemanticRead.schema());BrowserSemanticRead.validate(args);BrowserSemanticRead.validate(j("mode","text","frameRef",frame,"cursor",UUID.randomUUID()+":c0"));assertThrows(IllegalArgumentException.class,()->BrowserSemanticRead.validate(j("mode","text","frameRef","n0")));assertThrows(IllegalArgumentException.class,()->PluginRules.validateArguments(j("mode","text","allowedOrigins",new JSONArray()),BrowserSemanticRead.schema()));}
}
